(()=>{
 const byId=id=>uiElement(id),form=byId('welcomeAuth'),email=byId('welcomeEmail'),pass=byId('welcomePass'),note=byId('welcomeAuthNote');let mode='signup',busy=false,lastMail=0;
 function message(text,tone=''){note.textContent=text;note.dataset.tone=tone;}
 function select(next){if(busy)return;mode=next;message('');email.removeAttribute('aria-invalid');pass.removeAttribute('aria-invalid');const link=mode==='magic',signup=mode==='signup';byId('authTitle').textContent=link?'Sign in with an email link':signup?'Create your account':'Welcome back';byId('authSubtitle').textContent=link?'We’ll email you a link. No password needed.':signup?'A little setup. A more organised search.':'Pick up where you left off.';byId('authCreateTab').setAttribute('aria-selected',String(signup));byId('authLoginTab').setAttribute('aria-selected',String(!signup));byId('authPasswordField').classList.toggle('hidden',link);pass.required=!link;pass.autocomplete=signup?'new-password':'current-password';pass.placeholder=signup?'Create a password':'Enter your password';byId('authPasswordHint').classList.toggle('hidden',!signup);byId('welcomeRegister').classList.toggle('hidden',!signup);byId('welcomeSignIn').classList.toggle('hidden',mode!=='signin');byId('welcomeMagic').classList.toggle('hidden',!link);byId('authEmailLink').classList.toggle('hidden',link);byId('authUsePassword').classList.toggle('hidden',!link);byId('authCreateTab').tabIndex=signup?0:-1;byId('authLoginTab').tabIndex=signup?-1:0;}
 function friendly(err){const code=String(err?.code||''),msg=String(err?.message||'');if(/email_address_not_authorized|email address not authorized|smtp|error sending/i.test(code+' '+msg))return 'Email delivery is unavailable for this account. Please try again later or sign in with an existing password.';if(/email_exists|user_already_exists|already registered/i.test(code+' '+msg))return 'An account already exists with this email. Choose Sign in.';if(/signup_disabled/i.test(code+' '+msg))return 'Account creation is currently unavailable. Please try again later.';return authUserMessage(err);}
 async function submit(event){event.preventDefault();if(busy)return;email.value=email.value.trim();if(!email.validity.valid||!email.value){email.setAttribute('aria-invalid','true');message('Enter a valid email address.','error');email.focus();return;}email.removeAttribute('aria-invalid');if(mode!=='magic'&&(!pass.value||(mode==='signup'&&pass.value.length<8))){pass.setAttribute('aria-invalid','true');message(mode==='signup'?'Choose a password with at least 8 characters.':'Enter your password.','error');pass.focus();return;}pass.removeAttribute('aria-invalid');if(mode==='magic'&&Date.now()-lastMail<60000){message('Please wait a minute before requesting another email link.');return;}busy=true;const btn=byId(mode==='magic'?'welcomeMagic':mode==='signup'?'welcomeRegister':'welcomeSignIn'),label=btn.textContent;form.setAttribute('aria-busy','true');document.querySelectorAll('.auth-tabs button,#welcomeAuth button').forEach(b=>b.disabled=true);btn.textContent=mode==='magic'?'Sending link…':mode==='signup'?'Creating account…':'Signing in…';message('');try{const data=await authApi(mode,{email:email.value.toLowerCase(),password:pass.value});if(mode==='magic'){lastMail=Date.now();message('Link requested. If email delivery is available, check your inbox and spam folder, then open the link on this device.','success');return;}if(mode==='signup'&&!data.session){message('Check your email to confirm your account, then return here to sign in. If you already have an account, choose Sign in.','success');pass.value='';return;}if(!data.session||!data.user)throw Error('Sign-in could not finish. Please try again.');applySignedInUser(data.user);pass.value='';try{await hydrateFromRemote();persist();fillProfileForm();renderJobs();renderKanban();renderReview();renderNotifs();routeAfterAuth(true);}catch{toast('Signed in. Your saved workspace could not be restored. Please retry.');}}catch(err){message(friendly(err),'error');}finally{busy=false;form.removeAttribute('aria-busy');document.querySelectorAll('.auth-tabs button,#welcomeAuth button').forEach(b=>b.disabled=false);btn.textContent=label;}}
 byId('authCreateTab').addEventListener('click',()=>select('signup'));byId('authLoginTab').addEventListener('click',()=>select('signin'));byId('authEmailLink').addEventListener('click',()=>select('magic'));byId('authUsePassword').addEventListener('click',()=>select('signin'));form.addEventListener('submit',submit);byId('authShowPassword').addEventListener('click',e=>{const show=pass.type==='password';pass.type=show?'text':'password';e.target.textContent=show?'Hide':'Show';e.target.setAttribute('aria-pressed',String(show));e.target.setAttribute('aria-label',show?'Hide password':'Show password');});pass.addEventListener('keyup',e=>byId('authCapsLock').classList.toggle('hidden',!e.getModifierState('CapsLock')));document.querySelector('.auth-tabs').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'signup':e.key==='End'?'signin':mode==='signup'?'signin':'signup';select(next);byId(next==='signup'?'authCreateTab':'authLoginTab').focus();}});
 byId('welcomeContinue').addEventListener('click',()=>routeAfterAuth(true));
 const params=new URLSearchParams(location.hash.slice(1)||location.search.slice(1));const linkError=authRedirectIssue||params.get('error')||params.get('error_code');select(linkError?'magic':'signup');if(linkError)message('This sign-in link is invalid or expired. Request a new email link.','error');
})();
